fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    // For each string in the input vector, split it into lines
    // where each line remains a String.
    // If `keepends` is true, line endings are preserved,
    // otherwise they are stripped.
    // Each split yields one or more non-empty lines (never empty).

    a.into_iter().map(|s| {
        // Use standard split logic manually to preserve exact behavior.
        let mut lines = vec![];
        let mut start = 0;
        let bytes = s.as_bytes();

        for i in 0..bytes.len() {
            if bytes[i] == b'\n' {
                // slice from start to i (including '\n' if keepends)
                let end = if keepends { i + 1 } else { i };
                lines.push(s[start..end].to_string());
                start = i + 1;
            } else if bytes[i] == b'\r' {
                if i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                    // CRLF sequence
                    let end = if keepends { i + 2 } else { i };
                    lines.push(s[start..end].to_string());
                    start = i + 2;
                } else {
                    let end = if keepends { i + 1 } else { i };
                    lines.push(s[start..end].to_string());
                    start = i + 1;
                }
            }
        }
        // Any remaining text after last newline
        if start < s.len() {
            lines.push(s[start..].to_string());
        } else if lines.is_empty() {
            // If the string was empty, produce one empty string, ensuring non-empty lines
            lines.push(String::new());
        }

        // Ensure lines is never empty here, per spec
        // If somehow empty (should not happen), add empty string
        if lines.is_empty() {
            lines.push(String::new());
        }

        lines
    }).collect()
}